        return position;

    } else if (type == MSG_MULTIMEDIA) {

        buf.skipBytes(8); // serial number
        long timestamp = buf.readUnsignedInt() * 1000;
        buf.skipBytes(4 + 4 + 2 + 1 + 1 + 2); // gps
        buf.skipBytes(2 + 2 + 2 + 2); // cell

