        int mediaLength = buf.readInt();
        int mediaType = buf.readUnsignedByte();
        int mediaFormat = buf.readUnsignedByte();

        if (mediaType == 0 && mediaFormat == 0) {

            buf.readUnsignedByte(); // event

            ByteBuf photo;
            if (buf.readUnsignedShort() == 0) {
